"""One portable workspace for authenticated proximity and adaptive diagnostics."""
import base64,json,tempfile
from pathlib import Path
PURPOSE='adaptive_pipeline'
SCHEMA='tracehoi.AdaptivePipeline.v1'
FILES={'index.html','proximity.html','scene.html','distances.html','coverage.html','adaptive.html','surface_map.html','reference_annotation.html','TRACEHOI_MASK_REVIEW_RECORD_Z2x7Pf4Z.html','pipeline.json','README.md','files.json'}
def require(ok,msg):
 if not ok:raise ValueError(msg)
def unique(rows):
 ids=[r['id'] for r in rows];require(len(ids)==len(set(ids)),'duplicate_candidate');return {r['id']:r for r in rows}
def summarize(proximity,adaptive,mapped):
 """Join by immutable identities; array order is never a correspondence."""
 ps,ads,ms=[unique(x['candidates']) for x in [proximity,adaptive,mapped]]
 require(ps.keys()==ads.keys()==ms.keys() and len(ps)==4,'candidate_set')
 for key in ['case_id','object_binding','scene_frame','units','reference_status']:
  require(proximity[key]==adaptive[key]==mapped[key],'source_identity:'+key)
 require(adaptive['threshold']==mapped['threshold'] and adaptive['threshold_object_diagonal_ratio']==mapped['threshold_object_diagonal_ratio'],'threshold_identity')
 for x in [proximity,adaptive,mapped]:
  require(x['placement_ready'] is False and x['selected_candidate'] is None and x['accepted_scale'] is None,'source_acceptance')
 result=[]
 for id,p in ps.items():
  a,m=ads[id],ms[id]
  for key in ['hand_binding','collision_gate']:
   require(p[key]==a[key]==m[key],'candidate_identity:'+key)
  require(p['accepted'] is a['accepted'] is m['accepted'] is False,'candidate_accepted')
  profiles=[x for x in p['profiles'] if x['threshold']==adaptive['threshold'] and x['threshold_object_diagonal_ratio']==adaptive['threshold_object_diagonal_ratio']]
  require(len(profiles)==1,'threshold_profile');coarse=profiles[0];first,last=a['stages'][0],a['stages'][-1]
  for key in ['area_fraction_lower','area_fraction_upper','unresolved_area_fraction','areas','counts','total_area','threshold']:
   require(coarse[key]==first[key],'coarse_stage:'+key)
  require(last==m['stage'] and len(m['leaves'])==last['leaf_cells'],'map_stage')
  require(a['stop_reason']==m['stop_reason'],'stop_reason')
  require(first['unresolved_area_fraction']>=last['unresolved_area_fraction'],'uncertainty_increased')
  initial=first['unresolved_area_fraction'];final=last['unresolved_area_fraction']
  result.append(dict(id=id,hand_binding=p['hand_binding'],conditional_scale=p['conditional_scale'],collision_gate=p['collision_gate'],accepted=False,
   unsigned_surface_gap=p['unsigned_surface_gap'],vertex_distances=p['vertex_distances'],coarse=first,adaptive=last,stages=a['stages'],stop_reason=a['stop_reason'],
   unresolved_area_reduction=initial-final,unresolved_fraction_reduction=None if initial==0 else (initial-final)/initial,
   mapped_cells=len(m['leaves']),mapped_witnesses=len(m['witnesses'])))
 return result

def build(workspace,wsha,distances,dsha,coverage,csha,adaptive,asha,surface_map,msha,case,*mods,purpose):
 require(purpose==PURPOSE,'adaptive_pipeline_purpose_required')
 reader,export,pipeline,proximity,mapmod=mods[0],mods[5],mods[8],mods[11],mods[13]
 roots=[workspace,distances,coverage,adaptive,surface_map];originals=[pipeline.inventory(p,reader) for p in roots]
 with tempfile.TemporaryDirectory(prefix='tracehoi-adaptive-pipeline-') as t:
  copies=[Path(t).resolve()/n for n in ['workspace','distances','coverage','adaptive','surface_map']]
  for root,files in zip(copies,originals):export.publish(root,files,reader)
  args=[copies[0],wsha,copies[1],dsha,copies[2],csha,copies[3],asha,case,*mods[:13]]
  # This validates receipt, files, every saved query and the complete map viewer.
  audit=mapmod.verify(copies[4],msha,*args,purpose=mapmod.PURPOSE)
  prox,pfiles,paudit=proximity.build(copies[0],wsha,copies[1],dsha,copies[2],csha,case,*mods[:11],purpose=proximity.PURPOSE)
 wf,df,cf,af,mf=originals;ar=reader.parse(af['adaptive.json']);mr=reader.parse(mf['surface_map.json']);candidates=summarize(prox,ar,mr)
 report=dict(schema=SCHEMA,purpose=PURPOSE,case_id=case,status='adaptive_diagnostic_workspace_complete',candidates=candidates,
  source_workspace_binding=reader.binding(wf['workspace.json']),source_distance_binding=reader.binding(df['files.json']),source_coverage_binding=reader.binding(cf['files.json']),
  source_adaptive_binding=reader.binding(af['files.json']),source_surface_map_binding=reader.binding(mf['files.json']),object_binding=ar['object_binding'],
  threshold=ar['threshold'],threshold_object_diagonal_ratio=ar['threshold_object_diagonal_ratio'],scene_frame=ar['scene_frame'],units=ar['units'],
  reference_status=ar['reference_status'],human_review_record_complete=prox['human_review_record_complete'],independent_reference_complete=False,
  mask_accuracy_verified=False,geometric_accuracy_verified=False,physical_contact_verified=False,scale_identified=False,source_geometry_modified=False,
  selected_candidate=None,accepted_scale=None,placement_ready=False,full_parent_acceptance=False,new_surface_queries=0,source_queries_replayed=ar['new_surface_queries'],model_calls=0,
  verification_policy=dict(exact_source_bytes=True,exact_companion_viewers=True,adaptive_replay_policy='Inherited adaptive_coverage verifier; guarded arithmetic only. All classifications and nonnumeric fields remain exact.'),
  limitations=['The 2% object-diagonal threshold is a numerical diagnostic, not a contact criterion.',
   'Reduced unresolved area tightens computational bounds; it does not measure reconstruction accuracy.',
   'The minimum-scale candidate remains blocked for transverse crossings, regardless of coverage.',
   'Completed visual review does not replace the pending independent reference. Scale, contact and placement remain unaccepted.',
   'Companion viewers retain their original controls and default selections; dashboard selection does not change their state.'])
 files={'index.html':html(report,wf['scene/source/assets/original_rgb.png']),'pipeline.json':reader.encode(report),'proximity.html':pfiles['index.html'],
  'scene.html':pfiles['scene.html'],'distances.html':df['index.html'],'coverage.html':cf['index.html'],'adaptive.html':af['index.html'],
  'surface_map.html':mf['index.html'],'reference_annotation.html':af['reference_annotation.html'],
  'TRACEHOI_MASK_REVIEW_RECORD_Z2x7Pf4Z.html':pfiles['TRACEHOI_MASK_REVIEW_RECORD_Z2x7Pf4Z.html'],
  'README.md':b'TraceHOI unified adaptive diagnostic workspace\n\nExtract the entire ZIP and open index.html offline. Keep all companion files together. Each viewer keeps its own selection controls. pipeline.json records exact source receipts and joined candidate identities. The return evidence ZIP retains full source packets for verification. No geometry, mask, scale, contact or placement acceptance is changed. Preserve original review/reference JSON, terminal guards, source inputs and evidence archives.\n'}
 files['files.json']=reader.encode(dict(schema='tracehoi.AdaptivePipelineFiles.v1',files={n:reader.binding(b) for n,b in files.items()},placement_ready=False))
 require(set(files)==FILES,'output_inventory');require([pipeline.inventory(p,reader) for p in roots]==originals,'pipeline_sources_changed')
 return report,files,dict(surface_map=audit,proximity=paudit)

def verify(out,sha,*args,purpose):
 require(purpose==PURPOSE,'adaptive_pipeline_purpose_required');reader=args[11];pipeline=args[19];actual=pipeline.inventory(out,reader)
 require(set(actual)==FILES,'adaptive_pipeline_inventory');require(reader.binding(actual['files.json'])['sha256']==sha,'adaptive_pipeline_receipt')
 receipt=reader.parse(actual['files.json']);require(receipt['files']=={n:reader.binding(b) for n,b in actual.items() if n!='files.json'},'adaptive_pipeline_hashes')
 report,expected,audit=build(*args,purpose=purpose);require(actual==expected,'adaptive_pipeline_changed')
 return dict(verified=True,receipt_binding=reader.binding(actual['files.json']),numerical_audit=audit,placement_ready=False,selected_candidate=None)

def html(report,rgb):
 payload=json.dumps(report,separators=(',',':'),allow_nan=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
 return TEMPLATE.replace('__DATA__',payload).replace('__RGB__',base64.b64encode(rgb).decode()).encode()
TEMPLATE='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data:; script-src \'unsafe-inline\'; style-src \'unsafe-inline\'; connect-src \'none\'; base-uri \'none\'; form-action \'none\'"><title>TraceHOI · Adaptive pipeline</title><style>\n:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0b1320;color:#eaf3fa;font:15px/1.55 system-ui}main{max-width:1280px;margin:auto;padding:32px}header{display:grid;grid-template-columns:2fr 1fr;gap:28px}.eyebrow{font-size:12px;letter-spacing:2px;color:#74dbc4}h1{font-size:40px;line-height:1.15;margin:12px 0}h2{font-size:21px}p{color:#b6cada}.photo{width:100%;height:220px;object-fit:contain;background:#101f31;border-radius:12px}.badge{font-size:12px;padding:5px 12px;border:1px solid #355269;border-radius:20px;display:inline-block;margin:3px}.panel{background:#122337;border:1px solid #324e66;border-radius:12px;padding:22px;margin-top:22px}.warn{border-left:3px solid #e9b66b;background:#2d2923;padding:12px 17px}.links{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:22px}a{color:#a2ddfa}a.card{text-decoration:none;background:#152a40;padding:16px;border:1px solid #3b5a70;border-radius:10px}a.card strong{display:block;font-size:18px}a.card span{font-size:12px;color:#b2c9da}.grid{display:grid;grid-template-columns:1.6fr 1fr;gap:24px}label{display:inline-block;margin:0 20px 16px 0}select,button{font:inherit;color:inherit;background:#223d54;border:1px solid #7796aa;border-radius:6px;padding:7px}svg{width:100%;height:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;border-bottom:1px solid #365167;padding:10px}.scroll{overflow:auto}.big{font-size:29px;color:#8ce0c8}.small{font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}footer{margin:25px 0;color:#a5bbcd;font-size:12px}.strip{display:flex;flex-wrap:wrap;gap:8px}.strip a{padding:6px 10px;border:1px solid #38566b;border-radius:6px}:focus-visible{outline:2px solid #8ce0c8;outline-offset:3px}@media(max-width:800px){header,.grid{grid-template-columns:1fr}.links{grid-template-columns:1fr 1fr}main{padding:18px}h1{font-size:32px}}@media(max-width:480px){.links{grid-template-columns:1fr}}\n</style></head><body><main><header><div><div class="eyebrow">TRACEHOI / ADAPTIVE DIAGNOSTIC PIPELINE</div><h1>From scene to surface,<br>one connected workspace.</h1><p id="case"></p><span class="badge">4 diagnostic candidates</span><span class="badge">Human observation reviewed</span><span class="badge">Exact source receipts</span><p class="warn">Independent mask reference pending. Candidate scale, physical contact and pipeline placement remain unaccepted.</p></div><img class="photo" alt="Original RGB crop for this case" src="data:image/png;base64,__RGB__"></header>\n<nav class="links" aria-label="Pipeline stages"><a class="card" href="scene.html"><strong>01 · Scene</strong><span>Orbit the four unchanged hand–object pairs.</span></a><a class="card" href="distances.html"><strong>02 · Vertex distances</strong><span>Inspect nearest object-triangle witnesses.</span></a><a class="card" href="coverage.html"><strong>03 · Whole-face bounds</strong><span>Compare seven saved distance thresholds.</span></a><a class="card" href="adaptive.html"><strong>04 · Adaptive bounds</strong><span>Inspect the saved subdivision and query budget.</span></a><a class="card" href="surface_map.html"><strong>05 · Surface map</strong><span>Rotate the hand and inspect individual cells.</span></a><a class="card" href="reference_annotation.html"><strong>06 · Independent reference</strong><span>Complete the still-pending annotation separately.</span></a></nav>\n<section class="panel"><h2>What did subdivision resolve?</h2><p>Saved threshold: <strong id="threshold"></strong>. Teal is area certified within the numerical bound; the gold extension is unresolved area. Both bars use the same axis.</p><label>Inspect candidate <select id="candidate"></select></label><label>Chart scale <select id="axis"><option value="detail">Detail · 0–10% hand area</option><option value="full">Full · 0–100% hand area</option></select></label><div class="grid"><div><svg id="chart" viewBox="0 0 700 215" role="img" aria-label="Whole-face and adaptive coverage intervals"></svg><p class="small">This compares computational uncertainty at one fixed threshold. It does not measure reconstruction accuracy.</p></div><aside><div id="name"></div><div class="big" id="interval"></div><p id="reduction"></p><div class="warn" id="gate"></div><p class="small" id="budget"></p></aside></div><div class="scroll"><table><thead><tr><th>Candidate</th><th>Whole-face interval</th><th>Adaptive interval</th><th>Unresolved area reduction</th><th>Collision gate</th></tr></thead><tbody id="rows"></tbody></table></div></section>\n<section class="panel"><h2>Saved refinement history</h2><div class="scroll"><table><thead><tr><th>Depth</th><th>Cells</th><th>Queries used</th><th>Coverage interval</th><th>Unresolved hand area</th></tr></thead><tbody id="history"></tbody></table></div><p class="small">The surface map shows the final partition. Opening a companion viewer keeps that viewer\'s original controls and default selection.</p></section>\n<section class="panel"><h2>Evidence and remaining work</h2><p>Every companion viewer is copied exactly from authenticated evidence, except the proximity overview rebuilt through its published API. Source files are verified before this workspace is assembled. Existing adaptive queries are replayed for verification; no additional refinement is run.</p><div class="strip"><a href="proximity.html">Original proximity overview</a><a href="TRACEHOI_MASK_REVIEW_RECORD_Z2x7Pf4Z.html">Visual review form</a><a href="pipeline.json">Workspace JSON</a><a href="files.json">File receipts</a></div><p><button id="download">Download selected candidate evidence</button></p><details><summary>Source bindings and limitations</summary><pre id="sources"></pre></details></section><footer>Extract the entire workspace ZIP and keep its files together. Source geometry, masks and all four candidates are preserved. Offline diagnostic outputs are not placement approval.</footer><script id="data" type="application/json">__DATA__</script><script>\n(()=>{\'use strict\';const R=JSON.parse(document.getElementById(\'data\').textContent),$=id=>document.getElementById(id),label=s=>s.replaceAll(\'_\',\' \'),pct=n=>(100*n).toFixed(3)+\'%\',range=s=>pct(s.area_fraction_lower)+\' – \'+pct(s.area_fraction_upper);$(\'case\').textContent=R.case_id+\' · \'+R.scene_frame+\' · unverified scene units\';$(\'threshold\').textContent=(100*R.threshold_object_diagonal_ratio).toFixed(1)+\'% object diagonal (\'+R.threshold.toPrecision(6)+\' scene units)\';for(const c of R.candidates){let o=document.createElement(\'option\');o.value=c.id;o.textContent=label(c.id);$(\'candidate\').append(o)}$(\'sources\').textContent=JSON.stringify({sources:Object.fromEntries(Object.entries(R).filter(([k])=>k.startsWith(\'source_\')&&k.endsWith(\'_binding\'))),verification:R.verification_policy,limitations:R.limitations},null,2);\nfunction row(target,values){let tr=document.createElement(\'tr\');for(const v of values){let td=document.createElement(\'td\');td.textContent=v;tr.append(td)}target.append(tr);return tr}\nfunction draw(){const c=R.candidates.find(x=>x.id===$(\'candidate\').value),max=$(\'axis\').value===\'full\'?1:0.1; $(\'name\').textContent=label(c.id);$(\'interval\').textContent=range(c.adaptive);$(\'reduction\').textContent=c.unresolved_fraction_reduction===null?\'No unresolved area in the starting bounds.\':(100*c.unresolved_fraction_reduction).toFixed(1)+\'% less unresolved area (\'+pct(c.coarse.unresolved_area_fraction)+\' → \'+pct(c.adaptive.unresolved_area_fraction)+\' of the hand).\';$(\'gate\').textContent=\'Collision gate: \'+label(c.collision_gate)+\'. Candidate remains unaccepted.\';$(\'gate\').style.borderLeftColor=c.collision_gate.startsWith(\'blocked\')?\'#f08e86\':\'#81b9c9\';$(\'budget\').textContent=c.mapped_cells.toLocaleString()+\' mapped cells · \'+c.adaptive.queries_used.toLocaleString()+\' / \'+c.adaptive.query_budget.toLocaleString()+\' saved queries · stop: \'+label(c.stop_reason)+\'.\';let svg=\'<rect width="700" height="215" rx="8" fill="#0b1a2a"/>\';for(let i=0;i<=5;i++){let x=160+i*98;svg+=\'<line x1="\'+x+\'" x2="\'+x+\'" y1="25" y2="163" stroke="#314b61"/><text x="\'+x+\'" y="195" fill="#b6cad9" text-anchor="middle" font-size="12">\'+(max*100*i/5).toFixed(0)+\'%</text>\'}for(const [i,s]of[c.coarse,c.adaptive].entries()){let y=48+i*68;svg+=\'<text x="15" y="\'+(y+15)+\'" fill="#d5e5f1" font-size="13">\'+(i?\'Adaptive\':\'Whole face\')+\'</text><rect x="160" y="\'+y+\'" width="\'+(490*s.area_fraction_upper/max)+\'" height="22" fill="#e1b963"/><rect x="160" y="\'+y+\'" width="\'+(490*s.area_fraction_lower/max)+\'" height="22" fill="#7bd7bf"/><text x="160" y="\'+(y+41)+\'" fill="#d4e3ed" font-size="12">\'+range(s)+\'</text>\'}$(\'chart\').innerHTML=svg;$(\'rows\').replaceChildren();for(const x of R.candidates){const tr=row($(\'rows\'),[label(x.id),range(x.coarse),range(x.adaptive),x.unresolved_fraction_reduction===null?\'Already resolved\':(100*x.unresolved_fraction_reduction).toFixed(1)+\'%\',label(x.collision_gate)]);if(x.id===c.id)tr.style.background=\'#223f55\'}$(\'history\').replaceChildren();for(const s of c.stages)row($(\'history\'),[s.depth,s.leaf_cells,s.queries_used,range(s),pct(s.unresolved_area_fraction)])}\n$(\'candidate\').onchange=$(\'axis\').onchange=draw;$(\'download\').onclick=()=>{const c=R.candidates.find(x=>x.id===$(\'candidate\').value),record={schema:\'tracehoi.AdaptivePipelineSelection.v1\',case_id:R.case_id,candidate:c,source_surface_map_binding:R.source_surface_map_binding,placement_ready:false,accepted_scale:null,selected_candidate:null,physical_contact_verified:false,reference_status:R.reference_status};let u=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)+\'\\n\'],{type:\'application/json\'})),a=document.createElement(\'a\');a.href=u;a.download=\'tracehoi_adaptive_candidate_\'+c.id+\'.json\';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};draw();})();\n</script></main></body></html>\n'
